function drawPanelA(marker) {
  var selected = state.pattern === 'Alternating bad-good';
  var hi = state.highlighted && selected;
  var shade = draw.ellipse(260, 96).center(215, 92).fill(hi ? '#f1d36b' : '#d3d3d3').opacity(hi ? 0.92 : 0.95);
