  edge(270, 174, 355, 250, 2.1);

  box(185, 281, 180, 64, '(n−1)/2 − 1', 25);
  box(365, 281, 130, 64, '(n−1)/2', 25);

  dottedArrow(345, 112, 500, 112, marker);
  mathText('Θ(n)', 548, 112, 30);

  mathText('n', 145, 50, 31, { weight: hi ? 'bold' : 'normal' });
