  var prev = parentCenters.slice();

  for (var l = 1; l <= maxLevel; l++) {
    var count = 2 * Math.pow(2, l);
    var y = rowYs[l - 1];
    var centers = [];
    for (var i = 0; i < count; i++) {
      centers.push(minX + (maxX - minX) * ((i + 0.5) / count));
    }

    for (var p = 0; p < prev.length; p++) {
      var c1 = centers[2 * p];
      var c2 = centers[2 * p + 1];
      edge(prev[p], prevY, c1, y - 13, 1.25, '#222');
      edge(prev[p], prevY, c2, y - 13, 1.25, '#222');
    }

    var bw = l === 1 ? 48 : (l === 2 ? 33 : 21);
    var bh = l === 1 ? 23 : (l === 2 ? 19 : 14);
    var label = l === 1 ? '≈n/4' : (l === 2 ? '≈n/8' : '');
    for (var k = 0; k < centers.length; k++) {
      box(centers[k], y, bw, bh, (l < 3 && (l === 1 || k % 2 === 0)) ? label : '', l === 1 ? 13 : 10, 0.9);
    }

    prev = centers;
    prevY = y + bh / 2;
  }
}

function drawAccumulatedCost() {
  var groups = state.level + 1;
  var label = 'Accumulated grouped cost: ' + groups + ' × Θ(n)';
  var pattern = state.pattern === 'Balanced' ? 'balanced levels' : 'bad-good groups';
  var t = mathText(label + '  (' + pattern + ')', 600, 30, 18, { italic: false, strokeWidth: 4 });
  var bb = t.bbox();
  var r = draw.rect(bb.width + 18, bb.height + 8).center(600, 30).fill('#fff').opacity(0.86).stroke({ color: '#bbb', width: 1 });
  r.back();
  t.front();
  t.on('mousemove', function (e) {
    showTooltip('Each revealed grouped level contributes another Θ(n)-style band of work.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    showPopup('Accumulated cost', 'The label counts the visible cost groups, not the final closed-form running time. It is meant to show how grouping bad-good pairs makes their levels comparable to balanced levels.');
  });
  t.css('cursor', 'pointer');
}

function render() {
  draw.clear();
  var marker = makeArrowMarker();

  drawPanelA(marker);
  drawPanelB(marker);

  var labelY = state.level > 0 ? 432 : 390;
  mathText('(a)', 190, labelY, 28);
  mathText('(b)', 900, labelY, 28);

  drawAccumulatedCost();

  var underlineY = 424;
  if (state.pattern === 'Alternating bad-good') {
    draw.line(120, underlineY, 435, underlineY).stroke({ color: '#777', width: 2, linecap: 'round' }).attr({ 'stroke-dasharray': '4,5' });
  } else {
    draw.line(710, underlineY, 1088, underlineY).stroke({ color: '#777', width: 2, linecap: 'round' }).attr({ 'stroke-dasharray': '4,5' });
  }
}

function syncUi() {
  var cb = document.getElementById('splitPatternInput');
  if (cb) cb.checked = state.pattern === 'Balanced';
  var out = document.getElementById('expandLevelVal');
  if (out) out.value = levelNames[state.level];
}

function setExpansionByName(name) {
  var idx = levelNames.indexOf(name);
  state.level = idx < 0 ? 0 : idx;
}

function toggle_splitPattern(on) {
  state.pattern = on ? 'Balanced' : 'Alternating bad-good';
  state.highlighted = false;
  syncUi();
  render();
}

function trigger_expandLevel() {
  state.level = (state.level + 1) % levelNames.length;
  syncUi();
  render();
}

function applyDemoStep(i) {
  state.demoIndex = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[state.demoIndex];
  state.pattern = step.state.splitPattern;
  setExpansionByName(step.state.expandLevel);
  state.highlighted = state.demoIndex === 2;

  var narration = document.getElementById('demoNarration');
  if (narration) narration.textContent = step.narration;
  var stepLabel = document.getElementById('stepLabel');
  if (stepLabel) stepLabel.textContent = (state.demoIndex + 1) + ' / ' + demoSteps.length + ' — ' + step.title;
  syncUi();
  render();
}

function prevStep() {
  applyDemoStep(state.demoIndex - 1);
}

function nextStep() {
  applyDemoStep(state.demoIndex + 1);
}

applyDemoStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
