// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VBW = 1200;
var VBH_DEFAULT = 300;
var VBH_EXPANDED = 430;
draw.viewbox(0, 0, VBW, VBH_DEFAULT);
draw.attr({ preserveAspectRatio: 'xMidYMid meet' });

var state = {
  pattern: 'Alternating bad-good',
  level: 0,
  highlighted: false,
  demoIndex: 0
};

var levelNames = ['fragment', 'oneLevelExpanded', 'twoLevelsExpanded', 'threeLevelsExpanded'];
var demoSteps = [
  {
    title: 'Start with the bad-good fragment',
    narration: 'In the alternating case, the first split of n produces a 0 and an n−1 subproblem. The next split of n−1 is balanced, and the shaded ellipse groups those two partitioning calls together.',
