    state: { splitPattern: 'Balanced', expandLevel: 'twoLevelsExpanded' }
  }
];

function mathText(txt, x, y, size, opts) {
  opts = opts || {};
  var t = draw.text(txt)
    .font({
      family: 'Georgia, Times New Roman, serif',
      size: size,
      style: opts.italic === false ? 'normal' : 'italic',
      weight: opts.weight || 'normal'
    })
    .fill(opts.fill || '#000');
  if (opts.halo) {
    t.attr({
      'paint-order': 'stroke',
      stroke: opts.halo,
      'stroke-width': opts.strokeWidth == null ? 2.5 : opts.strokeWidth,
      'stroke-linejoin': 'round'
    });
  }
  t.center(x, y);
  return t;
}

function edge(x1, y1, x2, y2, w, color) {
  return draw.line(x1, y1, x2, y2).stroke({
    color: color || '#000',
    width: w || 1.7,
    linecap: 'butt'
