  g.rect(w, h).center(cx, cy).fill('#d9d9d9').opacity(opacity == null ? 1 : opacity).stroke('none');
  if (label) mathText(label, cx, cy + 2, size || 22);
  return g;
}

function attachCostInteraction(el, panelName) {
  el.on('mousemove', function (e) {
    showTooltip(panelName === 'left'
      ? 'Panel (a): Θ(n) groups the bad split on n with the following good split on n−1.'
      : 'Panel (b): Θ(n) is the single balanced partitioning call on n.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
