    state.highlighted = true;
    syncUi();
    render();
    showPopup(
      panelName === 'left' ? 'Grouped bad-good work' : 'One balanced level',
      panelName === 'left'
        ? 'The first split leaves a nearly unchanged n−1 subproblem, but the next split divides that subproblem about in half. The two partitioning calls together are still Θ(n) up to constant factors.'
        : 'The balanced split has one partitioning call of cost Θ(n), then two half-size subproblems. This is the level used for comparison with the grouped bad-good pair.'
    );
  });
  el.css('cursor', 'pointer');
}

function clickableShade(el, panelName) {
  attachCostInteraction(el, panelName);
}

function dottedArrow(x1, y, x2, panelName) {
  var g = draw.group();
  var shaftEnd = x2 - 23;

  g.line(x1, y, shaftEnd, y).stroke({
