  });

  var hit = g.line(x1, y, x2 + 12, y).stroke({
    color: '#fff',
    width: 20,
    opacity: 0
  });
  attachCostInteraction(hit, panelName);
  return g;
}

function drawPanelA() {
  var selected = state.pattern === 'Alternating bad-good';
  var hi = state.highlighted && selected;

  var shade = draw.ellipse(246, 86).center(215, 76).fill(hi ? '#efd36d' : '#d3d3d3').opacity(0.95);
  shade.rotate(29, 215, 76);
  clickableShade(shade, 'left');

  edge(138, 45, 36, 97, 1.8);
  edge(160, 45, 262, 97, 1.8);
