function drawPanelB() {
  var selected = state.pattern === 'Balanced';
  var hi = state.highlighted && selected;

  var shade = draw.ellipse(74, 38).center(888, 77).fill(hi ? '#efd36d' : '#d3d3d3').opacity(0.95);
