function drawExpansion(panel) {
  var isLeft = panel === 'left';
  var minX = isLeft ? 92 : 690;
  var maxX = isLeft ? 430 : 1080;
  var parentCenters = isLeft ? [170, 356] : [765, 1003];
  var prevY = isLeft ? 231 : 196;
  var rowYs = isLeft ? [284, 334, 379] : [250, 305, 360];
  var maxLevel = Math.min(state.level, 3);
  var prev = parentCenters.slice();

  for (var l = 1; l <= maxLevel; l++) {
    var count = 2 * Math.pow(2, l);
    var y = rowYs[l - 1];
    var centers = [];
    var i;
    for (i = 0; i < count; i++) {
      centers.push(minX + (maxX - minX) * ((i + 0.5) / count));
    }

    for (var p = 0; p < prev.length; p++) {
      edge(prev[p], prevY, centers[2 * p], y - 14, 1.05, '#222');
      edge(prev[p], prevY, centers[2 * p + 1], y - 14, 1.05, '#222');
    }

    var bw = l === 1 ? 50 : (l === 2 ? 34 : 22);
    var bh = l === 1 ? 24 : (l === 2 ? 18 : 13);
    var label = l === 1 ? '≈n/4' : (l === 2 ? '≈n/8' : '');
    for (i = 0; i < centers.length; i++) {
      box(centers[i], y, bw, bh, l < 3 && i % 2 === 0 ? label : '', l === 1 ? 12 : 9.5, 0.9);
    }

    prev = centers;
    prevY = y + bh / 2;
  }
}

