  mathText(label, cx, cy + 1, size || 26, { halo: '#d9d9d9', strokeWidth: 2.5 });
  return g;
}

function attachCostInteraction(el, panelName) {
  el.on('mousemove', function (e) {
    showTooltip(
      panelName === 'left'
        ? 'Panel (a): the Θ(n) tag counts the bad n split together with the following balanced split of n−1.'
        : 'Panel (b): the Θ(n) tag counts one balanced partitioning call on n.',
      e
    );
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    state.pattern = panelName === 'left' ? 'Alternating bad-good' : 'Balanced';
    state.highlighted = true;
    syncUi();
    render();
    showPopup(
      panelName === 'left' ? 'Grouped bad-good work' : 'One balanced level',
      panelName === 'left'
        ? 'The first split is very unbalanced, so it is not ignored. It is paired with the next balanced split, and the two costs are still Θ(n) up to constant factors.'
        : 'A balanced split spends Θ(n) once and leaves two half-size subproblems. This is the comparison target for the grouped bad-good pair.'
    );
  });
  el.css('cursor', 'pointer');
}

function dottedArrow(x1, y, x2, panelName) {
  var g = draw.group();
  g.line(x1, y, x2 - 34, y).stroke({
    color: '#000',
    width: 5,
    linecap: 'butt',
    dasharray: '3 6'
  });
  g.line(x2 - 28, y - 11, x2 - 28, y + 11).stroke({
    color: '#000',
    width: 3.2,
    linecap: 'butt'
  });
  g.polygon([[x2 - 24, y - 9], [x2 - 4, y], [x2 - 24, y + 9]])
    .fill('#000')
    .stroke('none');
  var hit = g.line(x1, y, x2 + 4, y).stroke({
    color: '#fff',
    width: 24,
    opacity: 0.001
  });
  attachCostInteraction(hit, panelName);
  return g;
}

function panelALabels(hi) {
  mathText('n', 145, 34, 35, { weight: hi ? 'bold' : 'normal', halo: '#d7d7d7', strokeWidth: 1.8 });
  mathText('0', 37, 141, 31, { halo: '#fff', strokeWidth: 2.6 });
  mathText('n−1', 263, 139, 31, { weight: hi ? 'bold' : 'normal', halo: '#d7d7d7', strokeWidth: 1.8 });
  mathText('Θ(n)', 515, 80, 33, { halo: '#fff', strokeWidth: 3 });
}

function panelBLabels(hi) {
  mathText('n', 845, 94, 35, { weight: hi ? 'bold' : 'normal', halo: '#d7d7d7', strokeWidth: 1.8 });
  mathText('Θ(n)', 1112, 91, 33, { halo: '#fff', strokeWidth: 3 });
}

function drawPanelA() {
  var selected = state.pattern === 'Alternating bad-good';
  var hi = state.highlighted && selected;

  var shade = draw.ellipse(270, 122).center(215, 84).fill(hi ? '#efd36d' : '#d7d7d7').stroke('none').opacity(1);
  shade.rotate(31, 215, 84);
  attachCostInteraction(shade, 'left');

  branch(133, 53, 35, 116, 2.4);
  branch(157, 53, 251, 116, 2.4);
  branch(252, 155, 190, 190, 2.4);
  branch(275, 155, 371, 190, 2.4);

  leafBox(197, 226, 194, 58, '(n−1)/2 − 1', 26);
  leafBox(370, 226, 138, 58, '(n−1)/2', 26);

  dottedArrow(345, 84, 486, 'left');
  panelALabels(hi);

  var hit = draw.ellipse(276, 128).center(215, 84).fill('#fff').opacity(0.001).stroke('none');
  hit.rotate(31, 215, 84);
  attachCostInteraction(hit, 'left');

  if (state.level > 0 && selected) drawExpansion('left');
}

function drawPanelB() {
  var selected = state.pattern === 'Balanced';
  var hi = state.highlighted && selected;

  var shade = draw.ellipse(86, 48).center(845, 92).fill(hi ? '#efd36d' : '#d7d7d7').stroke('none').opacity(1);
  attachCostInteraction(shade, 'right');

  branch(832, 111, 713, 176, 2.4);
  branch(858, 111, 986, 176, 2.4);

  leafBox(705, 221, 142, 58, '(n−1)/2', 26);
  leafBox(988, 221, 142, 58, '(n−1)/2', 26);

  dottedArrow(887, 91, 1075, 'right');
  panelBLabels(hi);

  var hit = draw.ellipse(92, 54).center(845, 92).fill('#fff').opacity(0.001).stroke('none');
  attachCostInteraction(hit, 'right');

  if (state.level > 0 && selected) drawExpansion('right');
}

function smallBox(cx, cy, w, h, label, fs) {
  var g = draw.group();
  g.rect(w, h).center(cx, cy).fill('#d9d9d9').stroke('none').opacity(0.94);
  if (label) mathText(label, cx, cy + 0.5, fs, { halo: '#d9d9d9', strokeWidth: 1.5 });
  return g;
}

function drawExpansion(panel) {
  var isLeft = panel === 'left';
  var bases = isLeft
    ? [{ x: 197, y: 255 }, { x: 370, y: 255 }]
    : [{ x: 705, y: 250 }, { x: 988, y: 250 }];
  var xMin = isLeft ? 105 : 590;
  var xMax = isLeft ? 455 : 1105;
  var rowYs = [315, 365, 408];
  var maxLevel = Math.min(state.level, 3);
  var parents = bases.slice();

  for (var l = 1; l <= maxLevel; l++) {
    var count = parents.length * 2;
    var y = rowYs[l - 1];
    var next = [];
    for (var i = 0; i < count; i++) {
      next.push({ x: xMin + (xMax - xMin) * ((i + 0.5) / count), y: y });
    }

    for (var p = 0; p < parents.length; p++) {
      branch(parents[p].x, parents[p].y, next[2 * p].x, y - 16, l === 1 ? 1.6 : 1.15);
      branch(parents[p].x, parents[p].y, next[2 * p + 1].x, y - 16, l === 1 ? 1.6 : 1.15);
    }

    var bw = l === 1 ? 58 : (l === 2 ? 38 : 24);
    var bh = l === 1 ? 27 : (l === 2 ? 19 : 13);
    var label = l === 1 ? '≈n/4' : (l === 2 ? '≈n/8' : '');
    var fs = l === 1 ? 13 : 9.5;
    for (i = 0; i < next.length; i++) {
      smallBox(next[i].x, y, bw, bh, i % 2 === 0 ? label : '', fs);
      next[i].y = y + bh / 2;
    }
    parents = next;
  }
}

function drawAccumulatedCost() {
  if (state.level <= 0) return;
  var groups = state.level + 1;
  var txt = 'visible grouped cost: ' + groups + ' × Θ(n)';
  var x = 575;
  var y = 24;
  var t = mathText(txt, x, y, 17, { italic: false });
  var bb = t.bbox();
  var r = draw.rect(bb.width + 18, bb.height + 8)
    .center(x, y)
    .fill('#fff')
    .opacity(0.92)
    .stroke({ color: '#bdbdbd', width: 1 });
  r.back();
  t.front();
  t.on('mousemove', function (e) {
    showTooltip('Each revealed band is being compared as one Θ(n) group of partitioning work.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    showPopup('Accumulated grouped cost', 'The counter marks how many comparable Θ(n) bands are visible. It is a guide to the grouping idea, not a substitute for the full recurrence proof.');
  });
  t.css('cursor', 'pointer');
}

function drawPanelLabels() {
  var labelY = state.level > 0 ? 427 : 283;
  mathText('(a)', 205, labelY, 28, { halo: '#fff', strokeWidth: 3 });
  mathText('(b)', 845, labelY, 28, { halo: '#fff', strokeWidth: 3 });
}

function render() {
  draw.clear();
  draw.viewbox(0, 0, VBW, state.level > 0 ? VBH_EXPANDED : VBH_DEFAULT);
  drawPanelA();
  drawPanelB();
  drawAccumulatedCost();
  drawPanelLabels();
}

function syncUi() {
  var cb = document.getElementById('splitPatternInput');
  if (cb) cb.checked = state.pattern === 'Balanced';
  var out = document.getElementById('expandLevelVal');
  if (out) out.textContent = levelNames[state.level];
}

function setExpansionByName(name) {
  var idx = levelNames.indexOf(name);
  state.level = idx < 0 ? 0 : idx;
}

function toggle_splitPattern(on) {
  state.pattern = on ? 'Balanced' : 'Alternating bad-good';
  state.highlighted = false;
  syncUi();
  render();
  showPopup(
    on ? 'Balanced view selected' : 'Alternating bad-good view selected',
    on
      ? 'The selected expansion now follows the balanced panel. One Θ(n) partitioning call creates two half-size subproblems.'
      : 'The selected expansion now follows the alternating bad-good panel. The bad split is counted, then paired with the following good split.'
  );
}

function trigger_expandLevel() {
  state.level = (state.level + 1) % levelNames.length;
  syncUi();
  render();
}

function applyDemoStep(i) {
  state.demoIndex = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[state.demoIndex];

  state.pattern = step.state.splitPattern;
  setExpansionByName(step.state.expandLevel);
  state.highlighted = state.demoIndex === 2;

  var narration = document.getElementById('demoNarration');
  if (narration) narration.textContent = step.narration;
  var stepLabel = document.getElementById('stepLabel');
  if (stepLabel) stepLabel.textContent = (state.demoIndex + 1) + ' / ' + demoSteps.length + ' — ' + step.title;

  syncUi();
  render();
}

function prevStep() {
  applyDemoStep(state.demoIndex - 1);
}

function nextStep() {
  applyDemoStep(state.demoIndex + 1);
}

applyDemoStep(0);
window.__markRendered();
